package br.com.admeclesial.application.financeiro;
import org.springframework.beans.factory.annotation.Autowired;
import br.com.admeclesial.application.usuario.SegurancaOrganizacaoService;
import br.com.admeclesial.domain.financeiro.*; import br.com.admeclesial.infrastructure.persistence.financeiro.*; import br.com.admeclesial.infrastructure.persistence.organizacao.OrganizacaoEclesialRepository; import br.com.admeclesial.infrastructure.persistence.pessoa.PessoaRepository; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.LocalDate; import java.util.*;
@Service public class ContribuicaoApplicationService { @Autowired SegurancaOrganizacaoService seguranca; final ContribuicaoRepository repo; final OrganizacaoEclesialRepository org; final PessoaRepository pessoa; final CategoriaFinanceiraRepository categorias; final ContaFinanceiraRepository contas; final DizimistaRepository dizimistas; final MovimentacaoFinanceiraRepository movimentos; final ContribuicaoMovimentacaoRepository links; public ContribuicaoApplicationService(ContribuicaoRepository r,OrganizacaoEclesialRepository o,PessoaRepository p,CategoriaFinanceiraRepository c,ContaFinanceiraRepository cf,DizimistaRepository d,MovimentacaoFinanceiraRepository m,ContribuicaoMovimentacaoRepository l){repo=r;org=o;pessoa=p;categorias=c;contas=cf;dizimistas=d;movimentos=m;links=l;} @Transactional public Contribuicao salvar(ContribuicaoRequest r){if(seguranca!=null)seguranca.validarAcesso(r.organizacaoEclesialUuid());var o=org.findByUuid(r.organizacaoEclesialUuid()).orElseThrow(()->new IllegalArgumentException("Organização não encontrada."));if(!o.isAtivo())throw new IllegalArgumentException("Organização inativa.");var conta=contas.findByUuid(r.contaFinanceiraUuid()).orElseThrow(()->new IllegalArgumentException("Conta financeira não encontrada."));if(!conta.getAtivo())throw new IllegalArgumentException("Conta financeira inativa.");if(!o.getId().equals(conta.getOrganizacaoEclesialId()))throw new IllegalArgumentException("A conta financeira deve pertencer à organização da contribuição.");Long pessoaId=null;if(r.pessoaUuid()!=null){var pe=pessoa.findByUuid(r.pessoaUuid()).orElseThrow(()->new IllegalArgumentException("Pessoa não encontrada."));if(!pe.isAtivo())throw new IllegalArgumentException("Pessoa inativa.");pessoaId=pe.getId();}if(r.tipo()==TipoContribuicao.DIZIMO && r.dizimistaUuid()==null)throw new IllegalArgumentException("Contribuição do tipo DIZIMO exige um dizimista."); Long dizimistaId=null;if(r.dizimistaUuid()!=null){var d=dizimistas.findByUuid(r.dizimistaUuid()).orElseThrow(()->new IllegalArgumentException("Dizimista não encontrado."));if(!d.getAtivo()||!d.getOrganizacaoEclesialId().equals(o.getId())||!d.getPessoaId().equals(pessoaId))throw new IllegalArgumentException("Dizimista incompatível com a contribuição.");if(r.dataContribuicao().isBefore(d.getDataInicio())||(d.getDataFim()!=null&&r.dataContribuicao().isAfter(d.getDataFim())))throw new IllegalArgumentException("Data da contribuição fora da vigência do dizimista.");dizimistaId=d.getId();}var cat=categorias.findByUuid(r.categoriaFinanceiraUuid()).orElseThrow(()->new IllegalArgumentException("Categoria financeira não encontrada."));if(!cat.getAtivo())throw new IllegalArgumentException("Categoria financeira inativa.");if(r.tipo()!=TipoContribuicao.DIZIMO&&r.dizimistaUuid()!=null)throw new IllegalArgumentException("Somente contribuição do tipo DIZIMO pode informar dizimista.");var e=new Contribuicao();e.setOrganizacaoEclesialId(o.getId());e.setPessoaId(pessoaId);e.setDizimistaId(dizimistaId);e.setCategoriaFinanceiraId(cat.getId());e.setTipo(r.tipo());e.setValor(r.valor());e.setDataContribuicao(r.dataContribuicao());e.setCompetencia(r.competencia());e.setMeioRecebimento(r.meioRecebimento());e.setObservacao(r.observacao());e=repo.save(e);var mov=new MovimentacaoFinanceira();mov.setContaFinanceiraId(conta.getId());mov.setCategoriaFinanceiraId(cat.getId());mov.setTipo(TipoMovimentacaoFinanceira.ENTRADA);mov.setValor(e.getValor());mov.setDataMovimentacao(e.getDataContribuicao());mov.setCompetencia(e.getCompetencia());mov.setDescricao("Contribuição " + e.getUuid());mov.setStatus(StatusMovimentacaoFinanceira.CONFIRMADA);mov=movimentos.save(mov);var link=new ContribuicaoMovimentacao();link.setContribuicaoId(e.getId());link.setMovimentacaoFinanceiraId(mov.getId());link.setValor(e.getValor());links.save(link);return e;} @Transactional(readOnly=true) public List<Contribuicao> listar(){return repo.findAllByOrderByDataContribuicaoDesc().stream().filter(e -> { try { if(seguranca!=null)seguranca.validarAcessoId(e.getOrganizacaoEclesialId()); return true; } catch (org.springframework.security.access.AccessDeniedException ex) { return false; }}).toList();}}
